import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        String bits = next();
        // zero[i] = number of 0s among the first i characters of the original string.
        int[] zero = new int[n + 1];
        for (int i = 0; i < n; i++) zero[i + 1] = zero[i] + (bits.charAt(i) == '0' ? 1 : 0);
        boolean flipped = false;
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < q; t++) {
            String op = next();
            if (op.equals("flip")) {
                flipped = !flipped;
            } else {
                int i = nextInt(), z = zero[i + 1];
                if (sb.length() > 0) sb.append(' ');
                sb.append(flipped ? i + 1 - z : z);
            }
        }
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := nextInt(), nextInt()
	bits := token()
	// zero[i] = number of 0s among the first i characters of the original string.
	zero := make([]int, n+1)
	for i := 0; i < n; i++ {
		zero[i+1] = zero[i]
		if bits[i] == '0' {
			zero[i+1]++
		}
	}
	flipped := false
	out := []string{}
	for t := 0; t < q; t++ {
		if string(token()) == "flip" {
			flipped = !flipped
		} else {
			i := nextInt()
			z := zero[i+1]
			if flipped {
				z = i + 1 - z
			}
			out = append(out, strconv.Itoa(z))
		}
	}
	fmt.Println(strings.Join(out, " "))
}
